"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View0 from "./components/cta-sections/variants/01-sunflower";
const views={"sunflower":View0};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"sunflower"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="sunflower",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}
